    PI_tx_busy = 1'b0;
    PI_pe_result = 16'b0000000000000000;
  end
  always @(posedge clock) begin
    // state 1
    if (cycle == 0) begin
      PI_rst <= 1'b0;
      PI_rx_data <= 8'b10000000;
      PI_rx_valid <= 1'b0;
      PI_legacy_idle <= 1'b0;
      PI_tx_busy <= 1'b0;
      PI_pe_result <= 16'b1000000000000000;
    end

    // state 2
    if (cycle == 1) begin
      PI_rst <= 1'b0;
      PI_rx_data <= 8'b01111110;
      PI_rx_valid <= 1'b1;
      PI_legacy_idle <= 1'b1;
      PI_tx_busy <= 1'b0;
      PI_pe_result <= 16'b0000000000000000;
    end

    // state 3
    if (cycle == 2) begin
      PI_rst <= 1'b0;
      PI_rx_data <= 8'b01111101;
      PI_rx_valid <= 1'b0;
      PI_legacy_idle <= 1'b1;
      PI_tx_busy <= 1'b0;
      PI_pe_result <= 16'b0000000000000000;
    end

    // state 4
    if (cycle == 3) begin
      PI_rst <= 1'b0;
      PI_rx_data <= 8'b01111110;
      PI_rx_valid <= 1'b1;
      PI_legacy_idle <= 1'b1;
      PI_tx_busy <= 1'b1;
      PI_pe_result <= 16'b0000000000000000;
